('recovery-zonerun-42', 'zonerun', 'recovery', 'Zone Run', 'maths', 2, array['any']::text[], 'The gas wall is coming. Do you make it into the safe zone, and is it faster to run or to take the buggy?', '{"scout":{"title":"Range finder","body":"Safe zone edge: 120 m away.\nYour buggy: right next to you.","big":true},"decoder":{"title":"Speeds","body":"Running: 6 m/s\nBuggy: 12 m/s\nRound every leg UP to whole seconds.","mono":true},"intel":{"title":"Zone timer","body":"The wall reaches you in 49 seconds."}}'::jsonb, '[{"label":"RUN or BUGGY (the faster one)","accept":["BUGGY"]},{"label":"Do you make it? YES / NO","accept":["YES"]}]'::jsonb, false, 5, 120, 'Running time = distance ÷ run speed. Buggy time = time to reach the buggy + distance ÷ buggy speed.', 'run 20s, buggy 10s → BUGGY; 10s vs 49s → YES', null, 25, 'published'),
